    private final Runnable enhancer = new Runnable() {
        @Override public void run() {
            if (!running460) return;
            try {
                View root = findViewById(android.R.id.content);
                LinearLayout content = content();
                int id = 0;
                if (content != null && content.getChildCount() > 0) id = System.identityHashCode(content.getChildAt(0));
                if (id != lastRoot460) {
                    lastRoot460 = id;
                    customScreen = detectCustomScreen(content);
                }
                wireNavigation();
                if (step() == 1) addCapacityPresets(root);
                if (step() == 2) enhanceItemPickerButtons(root);
                if (step() == 3) {
                    addOrganizerChooser(root);
                    addPhotoManager(root);
                    wireValidatedPreview(root);
                }
                enhanceEstimatedTotalLabels(root);
                if (isPreview(root)) enhancePreviewActions(root);
                if (isWizard(root)) addSaveDraftButton(root);
            } catch (Exception ignored) { }
            ui.postDelayed(this, 450);
        }
    };

    @Override public void onCreate(Bundle b) {
        super.onCreate(b);
        running460 = true;
        ui.postDelayed(enhancer, 500);
    }

    @Override protected void onResume() {
        super.onResume();
        if (!running460) { running460 = true; ui.postDelayed(enhancer, 300); }
    }

    @Override protected void onPause() {
        running460 = false;
        ui.removeCallbacks(enhancer);
        super.onPause();
    }

    @Override protected void onDestroy() {
        running460 = false;
        ui.removeCallbacks(enhancer);
        super.onDestroy();
    }

    @Override public void onBackPressed() {
        if ("saved460".equals(customScreen) || "catalog460".equals(customScreen)) {
            customScreen = "";
            invokeBase("showHome");
            return;
        }
        super.onBackPressed();
    }

