    private void wireNavigation(){
        LinearLayout nav=bottom(); if(nav==null)return;
        for(int i=0;i<nav.getChildCount();i++){
            View v=nav.getChildAt(i);
            if("v41_settings".equals(String.valueOf(v.getTag()))) { v.setOnClickListener(x->showSettings460()); continue; }
            String label=findLabel(v);
            if(label==null)continue;
            if(isSavedLabel(label)) v.setOnClickListener(x->showSaved460());
            else if(isCatalogLabel(label)) v.setOnClickListener(x->showCatalog460());
        }
        View root=findViewById(android.R.id.content);
        wireHomeTiles(root);
    }
    private String findLabel(View v){if(v instanceof TextView)return String.valueOf(((TextView)v).getText()).trim();if(v instanceof ViewGroup){ViewGroup g=(ViewGroup)v;for(int i=0;i<g.getChildCount();i++){String s=findLabel(g.getChildAt(i));if(s!=null&&(isSavedLabel(s)||isCatalogLabel(s)))return s;}}return null;}
    private boolean isSavedLabel(String s){return s.equals("Saved")||s.equals("محفوظ")||s.equals("المحفوظة")||s.equals("پاشەکەوتکراو");}
    private boolean isCatalogLabel(String s){return s.equals("Catalog")||s.equals("الكتالوج")||s.equals("کاتەلۆگ");}
    private void wireHomeTiles(View v){
        if(v instanceof TextView){String s=String.valueOf(((TextView)v).getText()).trim();ViewParent p=v.getParent();if(p instanceof View){if(s.equals("Saved offers")||s.equals("العروض المحفوظة")||s.equals("پێشنیارە پاشەکەوتکراوەکان"))((View)p).setOnClickListener(x->showSaved460());if(s.equals("Product catalog")||s.equals("كتالوج المنتجات")||s.equals("کاتەلۆگی بەرهەمەکان"))((View)p).setOnClickListener(x->showCatalog460());}}
        if(v instanceof ViewGroup){ViewGroup g=(ViewGroup)v;for(int i=0;i<g.getChildCount();i++)wireHomeTiles(g.getChildAt(i));}
    }
    private String detectCustomScreen(View v){if(hasExact(v,"v460_saved_title"))return"saved460";if(hasExact(v,"v460_catalog_title"))return"catalog460";return"";}
    private boolean hasExact(View v,String tag){if(v==null)return false;if(tag.equals(String.valueOf(v.getTag())))return true;if(v instanceof ViewGroup){ViewGroup g=(ViewGroup)v;for(int i=0;i<g.getChildCount();i++)if(hasExact(g.getChildAt(i),tag))return true;}return false;}
