    private Set<String> favorites(){return new HashSet<>(getSharedPreferences("offer_studio_settings",MODE_PRIVATE).getStringSet("favorite_items",new HashSet<>()));}
    private void setFavorite(String name,boolean on){Set<String> s=favorites();if(on)s.add(name);else s.remove(name);getSharedPreferences("offer_studio_settings",MODE_PRIVATE).edit().putStringSet("favorite_items",s).apply();}
    private ArrayList<String> recentNames(){ArrayList<String> out=new ArrayList<>();String raw=getSharedPreferences("offer_studio_settings",MODE_PRIVATE).getString("recent_items","");if(!raw.isEmpty())for(String s:raw.split("\u001E"))if(!s.isEmpty()&&!out.contains(s))out.add(s);return out;}
    private void addRecent(String name){ArrayList<String> a=recentNames();a.remove(name);a.add(0,name);while(a.size()>12)a.remove(a.size()-1);getSharedPreferences("offer_studio_settings",MODE_PRIVATE).edit().putString("recent_items",TextUtils.join("\u001E",a)).apply();}
    private String groupLabel(String k){switch(k){case"RECENT":return tx("Recent","الأخيرة","دوایین");case"FAVORITES":return tx("Favorites","المفضلة","دڵخواز");case"ALL":return tx("All","الكل","هەموو");case"PANELS":return tx("Panels","الألواح","پانێڵ");case"HYBRID":return tx("Hybrid Inverters","إنفرترات هجينة","ئینڤێرتەری هایبرید");case"ONGRID":return tx("On-Grid","أون كريد","ئۆن‌گرید");case"PUMP":return tx("Pump","مضخات","پەمپ");case"BATTERY":return tx("Batteries","البطاريات","باتری");case"STRUCTURE":return tx("Structures","الهياكل","هەیکەل");case"CABLE":return tx("Cables","الكيبلات","کەیبڵ");case"PROTECTION":return tx("Protection","الحماية","پاراستن");case"INSTALL":return tx("Install/Delivery","تركيب/نقل","دامەزراندن/گواستنەوە");default:return tx("Other","أخرى","هیتر");}}
    private String groupOf(OfferStudioActivity.Product p){String c=(p.category==null?"":p.category).toLowerCase(Locale.ROOT),n=(p.name==null?"":p.name).toLowerCase(Locale.ROOT);if(c.contains("panel"))return"PANELS";if(n.contains("pump")||n.contains("lar100"))return"PUMP";if(n.contains("on-grid")||n.contains("on grid")||n.contains("ongrid"))return"ONGRID";if(c.contains("inverter")||n.contains("inverter"))return"HYBRID";if(c.contains("battery")||n.contains("battery")||n.contains("bms"))return"BATTERY";if(c.contains("structure")||n.contains("structure")||n.contains("rack"))return"STRUCTURE";if(n.contains("cable")||n.contains("connector"))return"CABLE";if(c.contains("installation")||c.contains("delivery")||n.contains("installation")||n.contains("transport")||n.contains("delivery")||n.contains("civil")||n.contains("maintenance"))return"INSTALL";if(c.contains("accessor")||c.contains("earthing")||c.contains("lightning")||n.contains("breaker")||n.contains("spd")||n.contains("combiner")||n.contains("ats")||n.contains("meter")||n.contains("zero export"))return"PROTECTION";return"OTHER";}
    private boolean matchGroup(OfferStudioActivity.Product p,String g){if("ALL".equals(g))return true;if("FAVORITES".equals(g))return favorites().contains(p.name);if("RECENT".equals(g))return recentNames().contains(p.name);return g.equals(groupOf(p));}

    private void enhanceItemPickerButtons(View root){
        ArrayList<Button> buttons=new ArrayList<>();collectButtons(root,buttons);for(Button b:buttons){String s=String.valueOf(b.getText()).trim();if(isBrowseText(s)&&!"v460_picker".equals(String.valueOf(b.getTag()))){b.setTag("v460_picker");b.setOnClickListener(v->showEnhancedPicker(-1));}}
        ArrayList<TextView> replaces=new ArrayList<>();collectText(root,replaces);int idx=0;for(TextView t:replaces){String s=String.valueOf(t.getText()).trim();if(isReplaceText(s)){final int itemIndex=idx++;t.setOnClickListener(v->showEnhancedPicker(itemIndex));}}
    }
    private boolean isBrowseText(String s){return s.equals("Browse catalog")||s.equals("اختيار من الكتالوج")||s.equals("کاتەلۆگ ببینە");}
    private boolean isReplaceText(String s){return s.equals("Replace")||s.equals("استبدال")||s.equals("گۆڕین");}
    private void collectButtons(View v,ArrayList<Button> out){if(v instanceof Button)out.add((Button)v);if(v instanceof ViewGroup){ViewGroup g=(ViewGroup)v;for(int i=0;i<g.getChildCount();i++)collectButtons(g.getChildAt(i),out);}}
    private void collectText(View v,ArrayList<TextView> out){if(v instanceof TextView)out.add((TextView)v);if(v instanceof ViewGroup){ViewGroup g=(ViewGroup)v;for(int i=0;i<g.getChildCount();i++)collectText(g.getChildAt(i),out);}}

