    private void showPhotoManager(){OfferStudioActivity.Draft d=draft();if(d==null)return;Dialog dialog=new Dialog(this);dialog.setTitle(tx("Manage site photos","إدارة صور الموقع","بەڕێوەبردنی وێنەکانی شوێن"));LinearLayout outer=new LinearLayout(this);outer.setOrientation(LinearLayout.VERTICAL);outer.setPadding(dp(12),dp(10),dp(12),dp(12));ScrollView sc=new ScrollView(this);LinearLayout list=new LinearLayout(this);list.setOrientation(LinearLayout.VERTICAL);sc.addView(list);outer.addView(sc,new LinearLayout.LayoutParams(-1,0,1));Runnable[] refresh=new Runnable[1];refresh[0]=()->{list.removeAllViews();Set<String> excluded=excludedPhotos();if(d.photos.isEmpty())list.addView(text(tx("No photos attached","لا توجد صور مرفقة","هیچ وێنەیەک هاوپێچ نییە"),14,false,Color.rgb(104,119,132)));for(int i=0;i<d.photos.size();i++){final int idx=i;String uri=d.photos.get(i);LinearLayout row=new LinearLayout(this);row.setOrientation(LinearLayout.HORIZONTAL);row.setGravity(Gravity.CENTER_VERTICAL);row.setPadding(dp(6),dp(6),dp(6),dp(6));ImageView im=new ImageView(this);im.setScaleType(ImageView.ScaleType.CENTER_CROP);Bitmap bm=thumb(Uri.parse(uri));if(bm!=null)im.setImageBitmap(bm);row.addView(im,new LinearLayout.LayoutParams(dp(58),dp(58)));CheckBox include=new CheckBox(this);include.setText(tx("Include","تضمين","ناوخۆ"));include.setChecked(!excluded.contains(uri));row.addView(include,new LinearLayout.LayoutParams(0,dp(58),1));Button up=mini("↑"),down=mini("↓"),del=mini("×");row.addView(up,new LinearLayout.LayoutParams(dp(46),dp(46)));row.addView(down,new LinearLayout.LayoutParams(dp(46),dp(46)));row.addView(del,new LinearLayout.LayoutParams(dp(46),dp(46)));include.setOnCheckedChangeListener((b,on)->{Set<String>x=excludedPhotos();if(on)x.remove(uri);else x.add(uri);saveExcluded(x);});up.setOnClickListener(v->{if(idx>0){Collections.swap(d.photos,idx,idx-1);refresh[0].run();}});down.setOnClickListener(v->{if(idx<d.photos.size()-1){Collections.swap(d.photos,idx,idx+1);refresh[0].run();}});del.setOnClickListener(v->{d.photos.remove(idx);Set<String>x=excludedPhotos();x.remove(uri);saveExcluded(x);refresh[0].run();});list.addView(row,new LinearLayout.LayoutParams(-1,dp(70)));}};refresh[0].run();Button done=new Button(this);done.setAllCaps(false);done.setText(tx("Done","تم","تەواو"));done.setOnClickListener(v->{dialog.dismiss();setStep(3);invokeBase("showWizard");});outer.addView(done,new LinearLayout.LayoutParams(-1,dp(50)));dialog.setContentView(outer);dialog.show();Window w=dialog.getWindow();if(w!=null)w.setLayout((int)(getResources().getDisplayMetrics().widthPixels*.96),(int)(getResources().getDisplayMetrics().heightPixels*.76));}
