    private BigDecimal num(String s,BigDecimal def){if(s==null||s.trim().isEmpty())return def;try{return new BigDecimal(s.replace(",","").replace("$","").replace("IQD","").replace("USD","").trim());}catch(Exception e){return def;}}
    private BigDecimal lineTotal(OfferStudioActivity.LineItem i){return num(i.qty,BigDecimal.ONE).multiply(num(i.price,BigDecimal.ZERO));}
    private BigDecimal grandTotal(){BigDecimal t=BigDecimal.ZERO;OfferStudioActivity.Draft d=draft();if(d!=null)for(OfferStudioActivity.LineItem i:d.items)t=t.add(lineTotal(i));return t;}
    private String currency(){return getSharedPreferences("offer_studio_settings",MODE_PRIVATE).getString("currency","USD");}
    private String money(BigDecimal b){return fmt.format(b)+("IQD".equals(currency())?" IQD":" $");}
    private void enhanceEstimatedTotalLabels(View root){View a=findTagged(root,"v440_grand"),b=findTagged(root,"v440_preview_total");if(a instanceof TextView)((TextView)a).setText(tx("Estimated Total: ","المجموع التقديري: ","کۆی خەمڵاندراو: ")+money(grandTotal()));if(b instanceof TextView)((TextView)b).setText(tx("Estimated Total: ","المجموع التقديري: ","کۆی خەمڵاندراو: ")+money(grandTotal()));}
    private View findTagged(View v,String tag){if(v==null)return null;if(tag.equals(String.valueOf(v.getTag())))return v;if(v instanceof ViewGroup){ViewGroup g=(ViewGroup)v;for(int i=0;i<g.getChildCount();i++){View r=findTagged(g.getChildAt(i),tag);if(r!=null)return r;}}return null;}

    private void enhancePreviewActions(View root){
        Button share=findButton(root,new String[]{"Share PDF","مشاركة PDF","PDF هاوبەش بکە"});Button save=findTagged(root,"v440_save_pdf") instanceof Button?(Button)findTagged(root,"v440_save_pdf"):null;if(share!=null&&!"v460_share".equals(String.valueOf(share.getTag()))){share.setTag("v460_share");share.setOnClickListener(v->{if(validateOrShow()){saveQuiet();File pdf=buildPdf460();if(pdf!=null)shareGeneric(pdf);}});}if(save!=null&&!"v460_save".equals(String.valueOf(save.getTag()))){save.setTag("v460_save");save.setOnClickListener(v->{if(validateOrShow()){saveQuiet();File pdf=buildPdf460();if(pdf!=null)saveToPhone(pdf);}});}if(hasExact(root,"v460_extra_pdf"))return;if(share==null||share.getParent()==null)return;ViewParent p=share.getParent();if(!(p instanceof ViewGroup))return;ViewParent pp=((ViewGroup)p).getParent();if(!(pp instanceof LinearLayout))return;LinearLayout page=(LinearLayout)pp;LinearLayout row=new LinearLayout(this);row.setTag("v460_extra_pdf");row.setOrientation(LinearLayout.HORIZONTAL);row.setPadding(dp(18),0,dp(18),dp(10));Button wa=action(tx("WhatsApp PDF","PDF عبر واتساب","PDF بە واتسئاپ"));Button data=action(tx("Share PDF + Data","مشاركة PDF + البيانات","PDF + داتا هاوبەش بکە"));row.addView(wa,new LinearLayout.LayoutParams(0,dp(46),1));LinearLayout.LayoutParams dl=new LinearLayout.LayoutParams(0,dp(46),1);dl.leftMargin=dp(6);row.addView(data,dl);wa.setOnClickListener(v->{if(validateOrShow()){saveQuiet();File pdf=buildPdf460();if(pdf!=null)shareWhatsApp(pdf);}});data.setOnClickListener(v->{if(validateOrShow()){saveQuiet();File pdf=buildPdf460();File json=buildJson460(pdf);if(pdf!=null&&json!=null)sharePdfAndJson(pdf,json);}});page.addView(row);}
    private Button findButton(View v,String[] vals){if(v instanceof Button){String s=String.valueOf(((Button)v).getText()).trim();for(String x:vals)if(x.equals(s))return(Button)v;}if(v instanceof ViewGroup){ViewGroup g=(ViewGroup)v;for(int i=0;i<g.getChildCount();i++){Button b=findButton(g.getChildAt(i),vals);if(b!=null)return b;}}return null;}
    private void saveQuiet(){capture();invokeBase("saveOffer");}
    private String safeFile(String s){if(s==null)return"";return s.trim().replaceAll("[^\\p{L}\\p{N}_-]+","_").replaceAll("_+","_").replaceAll("^_|_$","");}
    private String baseFileName(){OfferStudioActivity.Draft d=draft();String client=safeFile(d==null?"":d.client);String cap=safeFile(d==null?"":d.capacity);String date=safeFile(d==null?"":d.date);String x=(client.isEmpty()?"Client":client)+(cap.isEmpty()?"":"_"+cap)+(date.isEmpty()?"":"_"+date);return x;}
    private boolean showPrices(){return getSharedPreferences("offer_studio_settings",MODE_PRIVATE).getBoolean("showPrices",true);}
    private boolean includePhotosPdf(){return getSharedPreferences("offer_studio_settings",MODE_PRIVATE).getBoolean("include_photos_pdf",true);}
    private ArrayList<String> includedPhotos(){ArrayList<String> out=new ArrayList<>();OfferStudioActivity.Draft d=draft();if(d==null||!includePhotosPdf())return out;Set<String> excluded=excludedPhotos();for(String u:d.photos)if(!excluded.contains(u))out.add(u);return out;}
    private File buildPdf460(){OfferStudioActivity.Draft d=draft();if(d==null)return null;try{File dir=getExternalFilesDir(Environment.DIRECTORY_DOCUMENTS);if(dir==null)return null;dir.mkdirs();File file=new File(dir,baseFileName()+".pdf");PdfDocument doc=new PdfDocument();Writer460 w=new Writer460(doc);w.newPage();w.header();w.section(tx("CLIENT","العميل","کڕیار"));w.row(tx("Client","العميل","کڕیار"),dash(d.client));w.row(tx("Phone","رقم الهاتف","ژمارەی تەلەفۆن"),dash(d.phone));w.row(tx("Location","الموقع","شوێن"),dash(d.location));w.row(tx("Date","التاريخ","بەروار"),dash(d.date));w.section(tx("SYSTEM","المنظومة","سیستەم"));w.row(tx("Type","النوع","جۆر"),dash(d.system));w.row(tx("Capacity","السعة","توانا"),dash(d.capacity));w.row(tx("Phase","الطور","فاز"),dash(d.phase));w.section(tx("REQUIRED ITEMS","المواد المطلوبة","ماددە پێویستەکان"));w.itemHeader();for(OfferStudioActivity.LineItem i:d.items)w.item(i);if(showPrices())w.big(tx("Estimated Total: ","المجموع التقديري: ","کۆی خەمڵاندراو: ")+money(grandTotal()),Color.rgb(20,153,112));w.section(tx("ORGANIZER DETAILS","بيانات المنظم","زانیاری ڕێکخەر"));w.row(tx("Installation","التركيب","دامەزراندن"),d.installation?tx("Included","مشمول","ناوخۆکراوە"):tx("Not included","غير مشمول","ناوخۆنەکراوە"));w.row(tx("Transport","النقل","گواستنەوە"),d.transport?tx("Included","مشمول","ناوخۆکراوە"):tx("Not included","غير مشمول","ناوخۆنەکراوە"));w.row(tx("Organizer","منظم الكشف","ڕێکخەر"),dash(d.organizer));w.row(tx("Included photos","الصور المضمنة","وێنە ناوخۆکراوەکان"),String.valueOf(includedPhotos().size()));if(!empty(d.notes)){w.section(tx("LOAD / NOTES","التحميل / الملاحظات","بار / تێبینی"));w.paragraph(d.notes);}w.finish();ArrayList<String> ph=includedPhotos();for(int i=0;i<ph.size();i++){Bitmap bm=decode(Uri.parse(ph.get(i)));if(bm==null)continue;w.newPage();w.smallHeader(tx("Site Photo ","صورة الموقع ","وێنەی شوێن ")+(i+1));float scale=Math.min(500f/bm.getWidth(),680f/bm.getHeight());int nw=(int)(bm.getWidth()*scale),nh=(int)(bm.getHeight()*scale),left=(595-nw)/2,top=92;w.canvas.drawBitmap(bm,null,new Rect(left,top,left+nw,top+nh),null);w.finish();bm.recycle();}FileOutputStream out=new FileOutputStream(file);doc.writeTo(out);out.close();doc.close();return file;}catch(Exception e){Toast.makeText(this,tx("PDF error: ","خطأ PDF: ","هەڵەی PDF: ")+e.getMessage(),Toast.LENGTH_LONG).show();return null;}}
    private File buildJson460(File pdf){OfferStudioActivity.Draft d=draft();if(d==null||pdf==null)return null;try{JSONObject root=d.json();root.put("form_type","organizer_preliminary_solar_form");root.put("estimated_total",grandTotal().toPlainString());root.put("currency",currency());JSONArray photos=new JSONArray();for(String x:includedPhotos())photos.put(x);root.put("included_photos",photos);root.put("company",getSharedPreferences("offer_studio_settings",MODE_PRIVATE).getString("company_name","Infinity Green Power"));File f=new File(pdf.getParentFile(),baseFileName()+".json");FileOutputStream out=new FileOutputStream(f);out.write(root.toString(2).getBytes("UTF-8"));out.close();return f;}catch(Exception e){return null;}}
    private String dash(String s){return empty(s)?"—":s.trim();}
    private boolean empty(String s){return s==null||s.trim().isEmpty();}
    private Uri fileUri(File f){return new Uri.Builder().scheme("content").authority(getPackageName()+".provider").appendPath(f.getName()).build();}
    private void shareGeneric(File f){Intent i=new Intent(Intent.ACTION_SEND);i.setType("application/pdf");i.putExtra(Intent.EXTRA_STREAM,fileUri(f));i.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);startActivity(Intent.createChooser(i,tx("Share organizer form","مشاركة الاستمارة","هاوبەشکردنی فۆرم")));}
    private void shareWhatsApp(File f){try{Intent i=new Intent(Intent.ACTION_SEND);i.setType("application/pdf");i.putExtra(Intent.EXTRA_STREAM,fileUri(f));i.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);i.setPackage("com.whatsapp");startActivity(i);}catch(Exception e){shareGeneric(f);}}
    private void sharePdfAndJson(File pdf,File json){ArrayList<Uri> uris=new ArrayList<>();uris.add(fileUri(pdf));uris.add(fileUri(json));Intent i=new Intent(Intent.ACTION_SEND_MULTIPLE);i.setType("*/*");i.putParcelableArrayListExtra(Intent.EXTRA_STREAM,uris);i.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);startActivity(Intent.createChooser(i,tx("Share PDF + form data","مشاركة PDF + بيانات الاستمارة","PDF + داتای فۆرم هاوبەش بکە")));}
    private void saveToPhone(File f){pendingSave460=f;Intent i=new Intent(Intent.ACTION_CREATE_DOCUMENT);i.addCategory(Intent.CATEGORY_OPENABLE);i.setType("application/pdf");i.putExtra(Intent.EXTRA_TITLE,f.getName());startActivityForResult(i,SAVE_PDF_460);}
    @Override protected void onActivityResult(int req,int res,Intent data){super.onActivityResult(req,res,data);if(req==SAVE_PDF_460&&res==RESULT_OK&&data!=null&&data.getData()!=null&&pendingSave460!=null){try{InputStream in=new FileInputStream(pendingSave460);OutputStream out=getContentResolver().openOutputStream(data.getData(),"w");byte[] buf=new byte[8192];int n;while((n=in.read(buf))>0)out.write(buf,0,n);in.close();if(out!=null)out.close();Toast.makeText(this,tx("PDF saved successfully","تم حفظ PDF بنجاح","PDF بە سەرکەوتوویی پاشەکەوت کرا"),Toast.LENGTH_LONG).show();}catch(Exception e){Toast.makeText(this,tx("Could not save PDF","تعذر حفظ PDF","نەتوانرا PDF پاشەکەوت بکرێت"),Toast.LENGTH_LONG).show();}pendingSave460=null;}}
    private Bitmap decode(Uri u){try{InputStream a=getContentResolver().openInputStream(u);BitmapFactory.Options o=new BitmapFactory.Options();o.inJustDecodeBounds=true;BitmapFactory.decodeStream(a,null,o);if(a!=null)a.close();int s=1;while(o.outWidth/s>1200||o.outHeight/s>1200)s*=2;BitmapFactory.Options b=new BitmapFactory.Options();b.inSampleSize=s;InputStream in=getContentResolver().openInputStream(u);Bitmap bm=BitmapFactory.decodeStream(in,null,b);if(in!=null)in.close();return bm;}catch(Exception e){return null;}}

    private class Writer460{
        final PdfDocument doc;final Paint p=new Paint(Paint.ANTI_ALIAS_FLAG);PdfDocument.Page page;Canvas canvas;int n=0,y=0;Writer460(PdfDocument d){doc=d;}
        void newPage(){n++;page=doc.startPage(new PdfDocument.PageInfo.Builder(595,842,n).create());canvas=page.getCanvas();canvas.drawColor(Color.WHITE);y=90;}
        void finish(){if(page!=null){draw(getSharedPreferences("offer_studio_settings",MODE_PRIVATE).getString("company_name","Infinity Green Power")+" · Organizer Form",rtl()?555:40,820,9,false,Color.rgb(20,153,112));doc.finishPage(page);page=null;}}
        void ensure(int h){if(y+h>790){finish();newPage();smallHeader(tx("Form continued","تكملة الاستمارة","بەردەوامی فۆرم"));}}
        void header(){String company=getSharedPreferences("offer_studio_settings",MODE_PRIVATE).getString("company_name","Infinity Green Power");draw(company.toUpperCase(Locale.ROOT),rtl()?555:40,40,23,true,Color.rgb(15,54,89));draw(tx("Organizer Preliminary Solar Form","استمارة أولية للمنظومة الشمسية","فۆرمی سەرەتایی سیستەمی خۆرەوی"),rtl()?555:40,65,13,true,Color.rgb(20,153,112));p.setColor(Color.rgb(20,153,112));canvas.drawRect(40,80,555,83,p);y=100;}
        void smallHeader(String s){draw(s,rtl()?555:40,45,18,true,Color.rgb(15,54,89));p.setColor(Color.rgb(20,153,112));canvas.drawRect(40,61,555,64,p);y=78;}
        void section(String s){ensure(34);p.setColor(Color.rgb(15,54,89));canvas.drawRoundRect(40,y,555,y+24,8,8,p);draw(s,rtl()?545:50,y+16,11,true,Color.WHITE);y+=32;}
        void row(String k,String v){ensure(27);if(rtl()){draw(k,545,y+15,10,true,Color.rgb(104,119,132));draw(v,365,y+15,10,false,Color.rgb(18,32,45));}else{draw(k,45,y+15,10,true,Color.rgb(104,119,132));draw(v,180,y+15,10,false,Color.rgb(18,32,45));}p.setColor(Color.rgb(225,231,237));canvas.drawLine(40,y+23,555,y+23,p);y+=27;}
        void itemHeader(){ensure(24);draw(tx("ITEM","المادة","ماددە"),rtl()?555:45,y+15,8,true,Color.rgb(20,153,112));draw(tx("QTY","الكمية","بڕ"),rtl()?240:365,y+15,8,true,Color.rgb(20,153,112));if(showPrices()){draw(tx("UNIT PRICE","سعر الوحدة","نرخی یەکە"),rtl()?160:435,y+15,8,true,Color.rgb(20,153,112));draw(tx("LINE TOTAL","المجموع","کۆ"),rtl()?75:505,y+15,8,true,Color.rgb(20,153,112));}y+=22;}
        void item(OfferStudioActivity.LineItem i){ensure(28);draw(trim(i.name,42),rtl()?555:45,y+14,9,false,Color.rgb(18,32,45));draw(empty(i.qty)?"1":i.qty,rtl()?240:370,y+14,9,false,Color.rgb(18,32,45));if(showPrices()){draw(empty(i.price)?"—":money(num(i.price,BigDecimal.ZERO)),rtl()?160:430,y+14,8,false,Color.rgb(18,32,45));draw(money(lineTotal(i)),rtl()?75:500,y+14,8,true,Color.rgb(15,54,89));}p.setColor(Color.rgb(225,231,237));canvas.drawLine(40,y+22,555,y+22,p);y+=26;}
        void big(String s,int color){ensure(32);draw(s,rtl()?555:45,y+21,13,true,color);y+=32;}
        void paragraph(String s){for(String line:wrap(s,500,10)){ensure(18);draw(line,rtl()?555:40,y+14,10,false,Color.rgb(55,70,84));y+=17;}y+=6;}
        List<String> wrap(String text,float max,int size){ArrayList<String> out=new ArrayList<>();if(text==null)return out;p.setTextSize(size);for(String para:text.split("\\n",-1)){if(para.isEmpty()){out.add("");continue;}StringBuilder line=new StringBuilder();for(String word:para.split("\\s+")){String test=line.length()==0?word:line+" "+word;if(p.measureText(test)>max&&line.length()>0){out.add(line.toString());line=new StringBuilder(word);}else{if(line.length()>0)line.append(' ');line.append(word);}}if(line.length()>0)out.add(line.toString());}return out;}
        void draw(String s,float x,float yy,float size,boolean bold,int color){p.setColor(color);p.setTextSize(size);p.setTypeface(bold?Typeface.DEFAULT_BOLD:Typeface.DEFAULT);p.setTextAlign(rtl()?Paint.Align.RIGHT:Paint.Align.LEFT);canvas.drawText(s==null?"":s,x,yy,p);}
        String trim(String s,int max){if(s==null)return"";return s.length()<=max?s:s.substring(0,max-1)+"…";}
    }
